/* multiple choice: correct + wrong [{c,why}] → choices in random order, why keyed by letter */
function mc(r,o){
  const seen=new Set([JSON.stringify(o.correct)]),w=[];
  for(const x of o.wrongs){const k=JSON.stringify(x.c);if(x.c==null||seen.has(k))continue;seen.add(k);w.push(x);if(w.length===(o.n||4)-1)break}
  need(w.length===(o.n||4)-1);
  const all=shuf(r,[{c:o.correct,ok:true},...w]),why={};let ans;
  all.forEach((x,i)=>{if(x.ok)ans=LET[i];else why[LET[i]]=x.why});
  return {type:"mc",parts:o.parts,keys:o.keys,choices:all.map(x=>x.c),ans,why,steps:o.steps};
}
/* pick two: right [{c}], wrong [{c,why}] */
function multi(r,o){
  const seen=new Set(),rt=[],wr=[];
  for(const x of o.right){const k=JSON.stringify(x.c);if(seen.has(k))continue;seen.add(k);rt.push({...x,ok:true})}
  for(const x of o.wrongs){const k=JSON.stringify(x.c);if(seen.has(k))continue;seen.add(k);wr.push(x);if(wr.length===3)break}
  need(rt.length===2&&wr.length===3);
  const all=shuf(r,[...rt,...wr]),why={},ans=[];
  all.forEach((x,i)=>{if(x.ok){ans.push(LET[i]);why[LET[i]]=`${LET[i]} is right, but you missed one.`}else why[LET[i]]=x.why});
  // "X is right" lines name a letter; they are remapped with the rest when choices are shuffled
  return {type:"multi",parts:o.parts,keys:o.keys,choices:all.map(x=>x.c),ans,why,steps:o.steps};
}
const say=(t,show)=>show?{say:t,show}:{say:t};

/* ---------- 3.NBT.1 rounding ---------- */
const UN={10:{name:"ten",place:"ones",dig:n=>n%10},100:{name:"hundred",place:"tens",dig:n=>Math.floor(n/10)%10}};
