/* ---------- 3.NBT.2 add and subtract within 1,000 ---------- */
const D=n=>[Math.floor(n/100),Math.floor(n/10)%10,n%10];
const pad=n=>String(n).padStart(3," ");
function addWork(a,b){const A=D(a),B=D(b),o=A[2]+B[2],c1=o>9?1:0,t=A[1]+B[1]+c1,c2=t>9?1:0,hh=A[0]+B[0]+c2;
  const carry=(c2?"1":" ")+(c1?"1":" ")+" ",s=a+b,S=pad(s);
  const base={carry,top:pad(a),op:"+",bot:pad(b)};
  return {c1,c2,steps:[
   say(`Ones: ${A[2]} + ${B[2]} = ${o}.${c1?` Write ${o%10}, regroup 1 ten.`:""}`,{work:{...base,carry:" "+(c1?"1":" ")+" ",res:"  "+S[2]}}),
   say(`Tens: ${A[1]} + ${B[1]}${c1?" + 1 regrouped":""} = ${t}.${c2?` Write ${t%10}, regroup 1 hundred.`:""}`,{work:{...base,res:" "+S.slice(1)}}),
   say(`Hundreds: ${A[0]} + ${B[0]}${c2?" + 1 regrouped":""} = ${hh}. The sum is ${s}.`,{work:{...base,res:S}})]};
}
function subWork(a,b){const A=D(a),B=D(b),w=A.slice();
  for(let i=2;i>0;i--){if(w[i]<B[i]){w[i]+=10;w[i-1]-=1}} if(w[1]<B[1]){} // tens fixed by the loop when it reaches i=1
  const top=w.map((v,i)=>v!==A[i]?`<s>${A[i]}</s><sup>${v}</sup>`:String(A[i]));
  const d=a-b,base={top,op:"−",bot:pad(b)},b1=A[2]<B[2],zeroT=b1&&A[1]===0;
  const lines=[];
  if(b1)lines.push(zeroT?`Ones: ${A[2]} is smaller than ${B[2]}. The tens place is 0, so borrow from the hundreds: hundreds become ${w[0]}, tens become 9, ones become ${w[2]}.`
    :`Ones: ${A[2]} is smaller than ${B[2]}. Borrow 1 ten: tens go from ${A[1]} to ${A[1]-1}, ones become ${w[2]}.`);
  else lines.push(`Ones: ${A[2]} is not smaller than ${B[2]}, so no borrowing in the ones.`);
  if(!zeroT){const t0=b1?A[1]-1:A[1]; if(t0<B[1])lines.push(`Tens: ${t0} is smaller than ${B[1]}. Borrow 1 hundred: hundreds go from ${A[0]} to ${A[0]-1}, tens become ${t0+10}.`)}
  return {w,steps:[say(`Difference means subtract: ${a} − ${b}. Start with the ones.`,{work:{...base,top:pad(a),res:"   "}}),
   say(lines.join(" "),{work:{...base,res:"   "}}),
   say(`Now subtract each place: ${w[2]} − ${B[2]} = ${w[2]-B[2]}. ${w[1]} − ${B[1]} = ${w[1]-B[1]}. ${w[0]} − ${B[0]} = ${w[0]-B[0]}. The difference is ${d}.`,{work:{...base,res:pad(d)}}),
   say(`Check by adding: ${d} + ${b} = ${a}. ✔`)]};
}
function addPair(r){let a,b,k=0;do{a=ri(101,799);b=ri(101,899);k++}while((a+b>999||(a%10+b%10<10&&Math.floor(a/10)%10+Math.floor(b/10)%10<10))&&k<200);need(a+b<=999);return[a,b]}
function subPair(r){let a,b,k=0;do{a=ri(200,999);b=ri(101,a-12);k++}while(!(a%10<b%10||Math.floor(a/10)%10<Math.floor(b/10)%10)&&k<200);need(a-b>=10&&b>=100);return[a,b]}
const colAdd=(a,b)=>{const A=D(a),B=D(b);return A.reduce((s,v,i)=>s*10+((v+B[i])%10),0)};
const colAbs=(a,b)=>{const A=D(a),B=D(b);return A.reduce((s,v,i)=>s*10+Math.abs(v-B[i]),0)};
const noDec=(a,b)=>{const A=D(a),B=D(b);return A.reduce((s,v,i)=>s*10+(v<B[i]?v+10-B[i]:v-B[i]),0)}; // borrowed but never made the next place smaller
function sumWrongs(a,b){const s=a+b,{c1,c2}=addWork(a,b);return[
  {c:colAdd(a,b),why:`You forgot to regroup. When a place adds up to 10 or more, write the ones digit and regroup 1 to the next place.`},
  c1?{c:s-10,why:`That is 10 too few. The ones made a new ten. Add that regrouped ten to the tens.`}:{c:s+10,why:`That is 10 too many. Check the tens place again.`},
  c2?{c:s-100,why:`That is 100 too few. The tens made a new hundred. Add that regrouped hundred to the hundreds.`}:{c:s+100,why:`That is 100 too many. Check the hundreds place again.`},
  {c:Math.abs(a-b),why:`You subtracted. Sum means add.`},{c:s+10,why:`That is 10 too many. Check the tens place again.`},{c:s-1,why:`Check the ones place again.`}]}
