/* question body with tappable tokens */
let tokIdx=0;
/* key words a student found: each key word counts once, even if it appears twice */
function foundKeys(q,hl){const keys=new Set(q.keys),f=new Set();let i=0;
  q.parts.forEach(p=>{const t=typeof p==="string"?p:p.eq;if(t!=null)t.split(/\s+/).filter(Boolean).forEach(w=>{const n=norm(w);if(keys.has(n)&&hl&&hl.has(i))f.add(n);i++})});return f}
function bodyHTML(q,hl,mode){ // mode: 'tap' | 'check' | 'keys'
  tokIdx=0; const keys=new Set(q.keys), found=foundKeys(q,hl);
  const para=(t,cls)=>`<p class="${cls}">${t.split(/\s+/).filter(Boolean).map(w=>{const i=tokIdx++,n=norm(w),k=keys.has(n),on=hl&&hl.has(i);
    let c="tok"; if(mode==="tap"&&on)c+=" hl"; if(mode==="check"){if(on)c+=k?" hit":" hl";else if(k&&!found.has(n))c+=" miss"} if(mode==="keys"&&k)c+=" hit";
    return `<span class="${c}" data-t="${i}" ${mode==="tap"?`tabindex="0" role="button" aria-pressed="${!!on}"`:''}>${fmt(w)}</span>`}).join(" ")}</p>`;
  return q.parts.map(p=>{
    if(typeof p==="string")return para(p,"qtext"); if(p.eq)return para(p.eq,"qtext eq");
    if(p.img)return img(p.img); if(p.table)return tableHTML(p); if(p.arr)return arrHTML(...p.arr); if(p.svg)return partsSVG(p.svg);
    if(p.groups)return `<div class="fig">${groupsHTML(p.groups)}</div>`; if(p.viz)return vizHTML(p.viz); if(p.fig)return `<div class="figd"><span aria-hidden="true">🖼</span> ${fmt(p.fig)}</div>`; return"";
  }).join("");
}
