function finalize(q,skill){q.skill=skill;const words=new Set();q.parts.forEach(p=>{const t=typeof p==="string"?p:p.eq;if(t!=null)t.split(/\s+/).filter(Boolean).forEach(w=>words.add(norm(w)))});
  q.keys=[...new Set(q.keys.map(k=>norm(String(k))))].filter(k=>words.has(k));need(q.keys.length>=1);if(q.keys.length<2){const extra=[...words].filter(w=>/\d|∎/.test(w)&&!q.keys.includes(w));q.keys.push(...extra.slice(0,2-q.keys.length))}need(q.keys.length>=2);
  if(q.whyIn)Object.keys(q.whyIn).forEach(k=>{if(+k===q.ans||+k<0||isNaN(+k))delete q.whyIn[k]});if(q.type==="input")need(Number.isFinite(q.ans)&&q.ans>=0);return q}
function make(skill,seed){const r=RNG(seed);let last;for(let t=0;t<80;t++){try{return finalize(pick(r,G[skill])(r),skill)}catch(e){if(!(e instanceof Retry))throw e;last=e}}throw last||new Error("gen failed")}
return {make,skills:Object.keys(G),count:k=>G[k].length};
