function RNG(seed){let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
class Retry extends Error{}
const ri=(r,a,b)=>a+Math.floor(r()*(b-a+1)),pick=(r,a)=>a[Math.floor(r()*a.length)],need=c=>{if(!c)throw new Retry()};
const nz=(r,a,b)=>{let x=0;while(!x)x=ri(r,a,b);return x};
const shuf=(r,a)=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const LET="ABCDE",NAMES=["Mia","Jayden","Aaliyah","Carlos","Kenji","Zoe","Malik","Sofia","Imani","Diego","Ava","Elijah","Priya","Marcus","Layla","Noah","Amara","Luis","Hana","Jamal","Tasha","Andre","Keisha","Darius"];
