const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a),lcm=(a,b)=>a/gcd(a,b)*b;
const F=(a,b)=>`[${a}/${b}]`,simp=(a,b)=>{const g=gcd(a,b)||1;if(b<0){a=-a;b=-b}return [a/g,b/g]};
/* signed numbers: N(−3) → "−3" (a real minus sign), P wraps negatives in parentheses */
const D=(x,p=4)=>String(+(+x).toFixed(p));
const N=x=>x<0?"−"+D(-x):D(x),P=x=>x<0?`(${N(x)})`:N(x);
const FS=(a,b)=>{const [x,y]=simp(a,b);return y===1?N(x):(x<0?"−":"")+F(Math.abs(x),y)};
const MX=(a,b)=>{const [x,y]=simp(a,b);const w=Math.floor(Math.abs(x)/y),f=Math.abs(x)%y,s=x<0?"−":"";return y===1?N(x):w?`${s}${w} ${F(f,y)}`:`${s}${F(f,y)}`};
const C=n=>Math.abs(n)>=1000?(n<0?"−":"")+Math.abs(n).toLocaleString("en-US"):N(n),$=x=>"$"+(+x).toFixed(2);
/* linear expressions: lin(3,−2) → "3x − 2" */
const term=(m,v,first)=>{if(!m)return "";const a=Math.abs(m),c=a===1&&v?"":D(a);return (first?(m<0?"−":""):(m<0?" − ":" + "))+c+v};
const lin=(m,b,v="x")=>{let s=term(m,v,true);if(b){s+=s?(b<0?` − ${D(-b)}`:` + ${D(b)}`):N(b)}return s||"0"};
const quad=(a,b,c,v="x")=>{let s=term(a,v+"²",true);s+=term(b,v,!s);if(c)s+=s?(c<0?` − ${D(-c)}`:` + ${D(c)}`):N(c);return s||"0"};
const sup=n=>String(n).split("").map(d=>"⁰¹²³⁴⁵⁶⁷⁸⁹"["0123456789".indexOf(d)]||(d==="-"?"⁻":d)).join("");
function mc(r,o){const seen=new Set([JSON.stringify(o.correct)]),w=[],n=o.n||4;
  for(const x of MCFIX.order(r,o.correct,o.wrongs,n)){const k=JSON.stringify(x.c);if(x.c==null||x.c===""||seen.has(k))continue;seen.add(k);w.push(x);if(w.length===n-1)break}
  need(w.length===n-1);const all=shuf(r,[{c:o.correct,ok:true},...w]),why={};let ans;all.forEach((x,i)=>{if(x.ok)ans=LET[i];else why[LET[i]]=x.why});
  return {type:"mc",parts:o.parts,keys:o.keys,choices:all.map(x=>x.c),ans,why,steps:o.steps,...(o.fixed?{fixed:true}:{})}}
const W=(c,why)=>({c,why});
/* numeric multiple choice: wrong answers from common mistakes */
const mcN=(r,o)=>mc(r,{...o,correct:o.fmt?o.fmt(o.ans):N(o.ans),wrongs:o.wrongs.map(([v,why])=>W(o.fmt?o.fmt(v):N(v),why))});
const inp=o=>({type:"input",parts:o.parts,keys:o.keys,ans:o.ans,whyIn:o.whyIn||{},whyElse:o.whyElse,steps:o.steps});
const yes=(r,o)=>({type:"mc",fixed:true,parts:o.parts,keys:o.keys,choices:o.choices,ans:LET[o.choices.indexOf(o.correct)],why:Object.fromEntries(o.choices.map((c,i)=>[LET[i],o.why||"Look at the breakdown to see why."]).filter(([l])=>l!==LET[o.choices.indexOf(o.correct)])),steps:o.steps});
