const Q=v=>{if(Number.isInteger(v))return N(v);for(let d=2;d<=144;d++){const n=Math.round(v*d);if(Math.abs(n/d-v)<1e-9)return FS(n,d)}return D(v,3)};
const M=x=>(x<0?"−":"")+"$"+Math.abs(x).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});
const M0=x=>"$"+Math.round(x).toLocaleString("en-US");
const ord=n=>n+(n%100>=11&&n%100<=13?"th":["th","st","nd","rd"][n%10]||"th");
const PIR=(a,b)=>{const [x,y]=simp(a,b);return (x===1?"":x)+"π"+(y===1?"":"/"+y)};
const PI=(a,b=1)=>{const [x,y]=simp(a,b);return y===1?(x===1?"π":x===-1?"−π":N(x)+"π"):FS(x,y)+"π"};
const cx=(a,b)=>{if(!b)return N(a);const im=(Math.abs(b)===1?"":D(Math.abs(b)))+"i";return a?`${N(a)} ${b<0?"−":"+"} ${im}`:(b<0?"−":"")+im};
const xf=p=>p<0?`(x − ${-p})`:`(x + ${p})`;           /* (x + p) */
const sq=n=>{let k=1,m=n;for(let i=2;i*i<=m;i++)while(m%(i*i)===0){m/=i*i;k*=i}return [k,m]};
const rad=n=>{const [k,m]=sq(n);return m===1?String(k):(k===1?"":k)+"√"+m};
/* number choices: never offer a negative or impossible distractor when the real answer is positive */
const mcNs=(r,o)=>mcN(r,{...o,fmt:o.fmt||C,wrongs:o.wrongs.filter(([v])=>Number.isFinite(v)&&!(o.ans>=0&&v<0))});
const mc5=(r,o)=>mc(r,{...o,n:5}),mcN5=(r,o)=>mcNs(r,{...o,n:5});
const W$=(v,why)=>W(M(v),why);
