  if(v.lshape){const {W,H,cw,ch,cut}=v.lshape,u=Math.min(30,280/W),X=40,Y=24,p=[[0,0],[W-cw,0],[W-cw,ch],[W,ch],[W,H],[0,H]].map(([a,b])=>`${X+a*u},${Y+b*u}`).join(" ");
    let s=`<polygon points="${p}" fill="${VS}" stroke="${VK}" stroke-width="2.5"/>`;
    if(cut)s+=`<line x1="${X}" y1="${Y+ch*u}" x2="${X+(W-cw)*u}" y2="${Y+ch*u}" stroke="#C0392B" stroke-width="3" stroke-dasharray="7 5"/>`;
    s+=tx(X+(W-cw)*u/2,Y-8,W-cw,{s:14,w:700})+tx(X+(W-cw)*u+8,Y+ch*u/2+5,ch,{a:"start",s:14,w:700})+tx(X+(W-cw/2)*u,Y+ch*u-8,cw,{s:14,w:700})+tx(X+W*u+8,Y+(ch+H)/2*u+5,H-ch,{a:"start",s:14,w:700})+tx(X+W*u/2,Y+H*u+20,W,{s:14,w:700})+tx(X-8,Y+H*u/2+5,H,{a:"end",s:14,w:700});
    return svgw(X+W*u+36,Y+H*u+30,s,"a figure made of two rectangles")}
  if(v.tape){const {small,times}=v.tape,u=Math.min(46,420/times),X=90;let s=tx(X-10,30,"Small",{a:"end",s:12})+`<rect x="${X}" y="12" width="${u}" height="28" fill="${VS}" stroke="${VK}" stroke-width="2"/>`+tx(X+u/2,31,small,{s:13,w:700});
    s+=tx(X-10,80,"Large",{a:"end",s:12});for(let i=0;i<times;i++)s+=`<rect x="${X+i*u}" y="62" width="${u}" height="28" fill="#fff" stroke="${VK}" stroke-width="2"/>`+tx(X+i*u+u/2,81,small,{s:13,w:700});
    s+=`<path d="M${X} 98 v8 h${times*u} v-8" fill="none" stroke="${VK}" stroke-width="1.5"/>`+tx(X+times*u/2,124,`${times} × ${small} = ${times*small}`,{s:13,w:700});return svgw(X+times*u+20,132,s,"a tape diagram comparison")}
  if(v.amodel){const {a,b}=v.amodel,W=360,H=Math.min(220,60*b.length+40),X=60,Y=34,tw=a.reduce((x,y)=>x+Math.sqrt(y),0),th=b.reduce((x,y)=>x+Math.sqrt(y),0);let s="",x=X;
    a.forEach(av=>{const w=W*Math.sqrt(av)/tw;s+=tx(x+w/2,Y-10,av.toLocaleString(),{s:13,w:700});let y=Y;b.forEach(bv=>{const h=(H-40)*Math.sqrt(bv)/th;s+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${VS}" stroke="${VK}" stroke-width="2"/>`+tx(x+w/2,y+h/2+5,(av*bv).toLocaleString(),{s:12});y+=h});x+=w});
    let y=Y;b.forEach(bv=>{const h=(H-40)*Math.sqrt(bv)/th;s+=tx(X-8,y+h/2+5,bv.toLocaleString(),{a:"end",s:13,w:700});y+=h});return svgw(X+W+10,H+10,s,"an area model")}
  if(v.hgrid){const n=v.hgrid.shade,u=18;let s="";for(let c=0;c<10;c++)for(let r=0;r<10;r++){const i=c*10+r;s+=`<rect x="${4+c*u}" y="${4+r*u}" width="${u}" height="${u}" fill="${i<n?VS:"#fff"}" stroke="${VK}" stroke-width="1"/>`}
    s+=`<rect x="4" y="4" width="${10*u}" height="${10*u}" fill="none" stroke="${VK}" stroke-width="2.5"/>`;return svgw(10*u+8,10*u+8,s,`a hundred grid with ${n} shaded`,220)}
