    if(lines){const n={square:4,rectangle:2,"equilateral triangle":3,"regular hexagon":6,heart:1,parallelogram:0}[k];
      if(k==="rectangle")s+=dash(110,40,110,180)+dash(0,110,220,110);else if(k==="heart")s+=dash(110,30,110,200);else for(let i=0;i<n;i++){const a=(k==="square"?0:k==="equilateral triangle"?-Math.PI/2:0)+i*Math.PI/n;s+=dash((c[0]-100*Math.cos(a)).toFixed(1),(c[1]-100*Math.sin(a)).toFixed(1),(c[0]+100*Math.cos(a)).toFixed(1),(c[1]+100*Math.sin(a)).toFixed(1))}}
