    for(let i=-R;i<=R;i++){s+=`<line x1="${X(i)}" y1="${Y(-R)}" x2="${X(i)}" y2="${Y(R)}" stroke="#DCE4EC"/><line x1="${X(-R)}" y1="${Y(i)}" x2="${X(R)}" y2="${Y(i)}" stroke="#DCE4EC"/>`;
      if(i&&i%(P.lab||2)===0)s+=tx(X(i),C+15,i*step,{s:10})+tx(C-6,Y(i)+4,i*step,{a:"end",s:10})}
    s+=`<line x1="${X(-R)-6}" y1="${C}" x2="${X(R)+6}" y2="${C}" stroke="${VK}" stroke-width="2"/><line x1="${C}" y1="${Y(-R)+6}" x2="${C}" y2="${Y(R)-6}" stroke="${VK}" stroke-width="2"/>`+tx(X(R)+12,C+4,"x",{s:12,w:700})+tx(C,Y(R)-10,"y",{s:12,w:700});
    const clip=(x1,y1,x2,y2)=>{const pts=[];const add=(x,y)=>{if(x>=-R-1e-9&&x<=R+1e-9&&y>=-R-1e-9&&y<=R+1e-9)pts.push([x,y])};
      if(x1===x2){add(x1,-R);add(x1,R)}else{const m=(y2-y1)/(x2-x1),b=y1-m*x1;add(-R,m*-R+b);add(R,m*R+b);if(m){add((R-b)/m,R);add((-R-b)/m,-R)}}return pts.length>=2?[pts[0],pts[pts.length-1]]:null};
    (P.lines||[]).forEach(([x1,y1,x2,y2,dash])=>{const c=clip(x1,y1,x2,y2);if(c)s+=`<line x1="${X(c[0][0])}" y1="${Y(c[0][1])}" x2="${X(c[1][0])}" y2="${Y(c[1][1])}" stroke="#1F6FD1" stroke-width="2.5" ${dash?'stroke-dasharray="6 5"':""}/>`});
